  ];

  var groupsEl = document.getElementById("groups");
  var emptyEl = document.getElementById("empty");
  var searchEl = document.getElementById("search");
  var countEl = document.getElementById("count");
  var toastEl = document.getElementById("toast");
  var settingsBtn = document.getElementById("settingsBtn");
  var settingsEl = document.getElementById("settings");
  var overlayEl = document.getElementById("overlay");
  var closeBtn = document.getElementById("closeSettings");
  var lastEsc = 0;

  function say(msg) {
    toastEl.textContent = msg;
    toastEl.classList.add("show");
    clearTimeout(say._t);
    say._t = setTimeout(function(){ toastEl.classList.remove("show"); }, 1300);
  }

  function esc(s) {
    return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
  }

  function shortUrl(u) {
    return u.replace(/^https?:\/\//, "");
  }

  function copyText(text, btn) {
    function ok() {
      btn.textContent = "ok";
      btn.classList.add("ok");
      say("copied");
      setTimeout(function(){ btn.textContent = "copy"; btn.classList.remove("ok"); }, 1000);
    }
    try {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(ok).catch(fallback);
      } else {
        fallback();
      }
    } catch(e) { fallback(); }

    function fallback() {
      var ta = document.createElement("textarea");
      ta.value = text;
      ta.style.cssText = "position:fixed;left:-9999px;top:0;opacity:0";
      document.body.appendChild(ta);
      ta.focus(); ta.select();
      try { document.execCommand("copy"); ok(); } catch(err) { say("copy failed"); }
      document.body.removeChild(ta);
    }
  }

  function render() {
    var html = "";
    DATA.forEach(function(g, i) {
      var links = "";
      g.l.forEach(function(u) {
        var domain = shortUrl(u).split("/")[0];
        var rest = shortUrl(u).slice(domain.length);
        links += '<div class="link" data-u="' + esc(u) + '">' +
          '<span class="url">https://<b>' + esc(domain) + '</b>' + esc(rest) + '</span>' +
          '<div class="actions">' +
            '<button class="btn copy" type="button">copy</button>' +
            '<a class="btn" href="' + esc(u) + '" target="_blank" rel="noopener">open</a>' +
          '</div></div>';
      });
      html += '' +
        '**Summary:**
<span class="kao">' + g.k + '</span><span class="gn">' + esc(g.n) + '</span>' +
        '<span class="pill">' + g.l.length + '</span><span class="chev">▾</span>' +
        '<div class="body">' + links + '</div>';
    });
    groupsEl.innerHTML = html;

    // bind copy buttons
    [].forEach.call(groupsEl.querySelectorAll(".btn.copy"), function(btn) {
      btn.addEventListener("click", function(e) {
        e.preventDefault();
        e.stopPropagation();
        var url = btn.closest(".link").getAttribute("data-u");
        copyText(url, btn);
      });
      btn.addEventListener("touchend", function(e) {
        e.preventDefault();
        e.stopPropagation();
        var url = btn.closest(".link").getAttribute("data-u");
        copyText(url, btn);
      }, {passive: false});
    });
  }

  function filter(q) {
    q = (q || "").trim().toLowerCase();
    var gCount = 0, lCount = 0;
    [].forEach.call(groupsEl.querySelectorAll(".group"), function(grp) {
      var name = grp.getAttribute("data-n") || "";
      var links = grp.getAttribute("data-l") || "";
      var matchName = !q || name.indexOf(q) !== -1;
      var shown = 0;
      [].forEach.call(grp.querySelectorAll(".link"), function(li) {
        var u = (li.getAttribute("data-u") || "").toLowerCase();
        var hit = matchName || u.indexOf(q) !== -1;
        li.style.display = hit ? "" : "none";
        if (hit) shown++;
      });
      var pill = grp.querySelector(".pill");
      if (pill) pill.textContent = shown;
      if (shown) {
        grp.style.display = "";
        gCount++;
        lCount += shown;
        if (q) grp.open = true;
      } else {
        grp.style.display = "none";
      }
    });
    countEl.innerHTML = "<b>" + gCount + "</b> groups · <b>" + lCount + "</b> links";
    emptyEl.classList.toggle("show", gCount === 0);
  }

  searchEl.addEventListener("input", function(){ filter(searchEl.value); });

  // SETTINGS open/close - Chromebook safe
  function openSettings() {
    settingsEl.classList.add("open");
    overlayEl.classList.add("open");
  }
  function closeSettings() {
    settingsEl.classList.remove("open");
    overlayEl.classList.remove("open");
  }

  function bindTap(el, fn) {
    if (!el) return;
    el.addEventListener("click", function(e){ e.preventDefault(); fn(); });
    el.addEventListener("touchend", function(e){ e.preventDefault(); fn(); }, {passive: false});
  }

  bindTap(settingsBtn, openSettings);
  bindTap(closeBtn, closeSettings);
  bindTap(overlayEl, closeSettings);

  // THEME
  [].forEach.call(document.querySelectorAll(".sw"), function(sw) {
    bindTap(sw, function() {
      var t = sw.getAttribute("data-t");
      document.body.setAttribute("data-theme", t);
      [].forEach.call(document.querySelectorAll(".sw"), function(s){ s.classList.remove("active"); });
      sw.classList.add("active");
      try { localStorage.setItem("pi-theme", t); } catch(e){}
    });
  });
  try {
    var saved = localStorage.getItem("pi-theme");
    if (saved) {
      document.body.setAttribute("data-theme", saved);
      [].forEach.call(document.querySelectorAll(".sw"), function(s){
        s.classList.toggle("active", s.getAttribute("data-t") === saved);
      });
    }
  } catch(e){}

  // ABOUT:BLANK
  bindTap(document.getElementById("aboutBlank"), function() {
    var win = window.open("about:blank", "_blank");
    if (!win) { say("popup blocked"); return; }
    try {
      var d = win.document;
      d.title = document.title;
      d.body.style.cssText = "margin:0;overflow:hidden;background:#000;height:100vh";
      var ifr = d.createElement("iframe");
      ifr.src = location.href;
      ifr.style.cssText = "position:fixed;inset:0;width:100%;height:100%;border:0";
      d.body.appendChild(ifr);
      say("opened in about:blank");
    } catch(err) {
      try { win.location = location.href; } catch(e2){}
    }
  });

  // AUTO CLOAK
  var autoCloakBtn = document.getElementById("autoCloak");
  var autoOn = false;
  try { autoOn = localStorage.getItem("pi-auto") === "1"; } catch(e){}
  if (autoOn) autoCloakBtn.classList.add("on");
  bindTap(autoCloakBtn, function() {
    autoOn = !autoOn;
    autoCloakBtn.classList.toggle("on", autoOn);
    try { localStorage.setItem("pi-auto", autoOn ? "1" : "0"); } catch(e){}
    if (autoOn) {
      var win = window.open("about:blank", "_blank");
      if (win) {
        try {
          var d = win.document;
          d.body.style.cssText = "margin:0;overflow:hidden;background:#000;height:100vh";
          var ifr = d.createElement("iframe");
          ifr.src = location.href;
          ifr.style.cssText = "position:fixed;inset:0;width:100%;height:100%;border:0";
          d.body.appendChild(ifr);
        } catch(e){}
      }
      setTimeout(function(){ location.replace("https://classroom.google.com/"); }, 400);
    }
  });

  // TAB CLOAK
  var cloaks = {
    classroom: { t: "Classes", f: "https://ssl.gstatic.com/classroom/favicon.png" },
    drive: { t: "My Drive - Google Drive", f: "https://ssl.gstatic.com/docs/doclist/images/drive_2022q3_32dp.png" },
    docs: { t: "Google Docs", f: "https://ssl.gstatic.com/docs/documents/images/kix-favicon7.ico" },
    google: { t: "Google", f: "https://www.google.com/favicon.ico" },
    blank: { t: "\u200b", f: "" },
    reset: { t: "Proxy Index", f: "" }
  };
  [].forEach.call(document.querySelectorAll(".preset"), function(btn) {
    bindTap(btn, function() {
      var key = btn.getAttribute("data-cloak");
      var c = cloaks[key];
      if (!c) return;
      document.title = c.t;
      var link = document.querySelector("link[rel*='icon']") || document.createElement("link");
      link.rel = "icon";
      link.href = c.f || "data:,";
      document.head.appendChild(link);
      [].forEach.call(document.querySelectorAll(".preset"), function(p){ p.classList.remove("active"); });
      btn.classList.add("active");
      say("tab: " + (c.t === "\u200b" ? "blank" : c.t));
    });
  });

  // PANIC + KEYS
  document.addEventListener("keydown", function(e) {
    if (e.key === "/" && document.activeElement !== searchEl) {
      e.preventDefault();
      searchEl.focus();
    }
    if (e.key === "Escape") {
      var now = Date.now();
      if (now - lastEsc < 400) {
        location.replace("https://classroom.google.com/");
      }
      lastEsc = now;
      closeSettings();
      if (searchEl.value) { searchEl.value = ""; filter(""); }
    }
  });

  render();
})();
